{
  "command": "find web proto deploy -type f | sort; printf '\\n---deploy---\\n'; nl -ba deploy/compose.yaml; nl -ba deploy/.env; nl -ba dns-server/Dockerfile; file dns-server/dns-server; shasum -a 256 dns-server/dns-server; git diff --cached --name-only",
  "timeout": 10
}

{
  "command": "for f in web/gateway/internal/{proxy/*.go,ratelimit/*.go,service/*.go,iamclient/*.go}; do echo ===$f; nl -ba \"$f\"; done",
  "timeout": 10
}

{
  "command": "for f in web/dnssync/internal/{server/*.go,hub/*.go,service/*.go,store/*.go}; do echo ===$f; nl -ba \"$f\"; done",
  "timeout": 10
}

{
  "command": "for f in web/frontend/nginx.conf web/frontend/ui/src/api/client.ts web/frontend/ui/src/auth/AuthContext.tsx web/frontend/ui/src/lib/navigation.ts web/frontend/ui/src/components/QrCode.tsx web/frontend/ui/src/main.tsx web/frontend/ui/package.json web/go.mod; do echo ===$f; nl -ba \"$f\"; done; grep -RInE 'dangerouslySetInnerHTML|innerHTML|localStorage|sessionStorage|window\\.location|href=|target=|eval\\(' web/frontend/ui/src",
  "timeout": 10
}

