     1	package proxy
     2	
     3	import (
     4		"context"
     5		"errors"
     6		"io"
     7		"log/slog"
     8		"net"
     9		"net/http"
    10		"net/http/httputil"
    11		"net/netip"
    12		"net/url"
    13		"strings"
    14		"sync/atomic"
