    22	)
    23	
    24	const (
    25		DefaultUpstreamTimeout = 30 * time.Second
    26		DefaultDialTimeout     = 5 * time.Second
    27		MaxTokenLength         = 512
    28		maxLoggedPath          = 256
    29	)
    30	
    31	type Introspector interface {
    32		Introspect(ctx context.Context, token string) (iamclient.Identity, error)
    33	}
    34	
    35	type Limiter interface {
    36		Allow(key string) (bool, time.Duration)
    37	}
    38	
    39	type Config struct {
    40		IAMURL          *url.URL
    41		BackendURL      *url.URL
    42		MaxBodyBytes    int64
    43		UpstreamTimeout time.Duration
    44		DialTimeout     time.Duration
    45		Transport       http.RoundTripper
    46	}
    47	
    48	type Handler struct {
    49		cfg          Config
    50		introspector Introspector
    51		limiter      Limiter
    52		log          *slog.Logger
    53		health       http.Handler
    54		proxies      map[Upstream]http.Handler
    55	}
    56	
    57	type state struct {
    58		upstream  Upstream
    59		principal string
    60		assertion string
    61		body      *limitedBody
    62	}
    63	
    64	type stateKey struct{}
    65	
    66	func stateFrom(ctx context.Context) *state {
    67		if st, ok := ctx.Value(stateKey{}).(*state); ok {
    68			return st
    69		}
    70		return &state{}
    71	}
    72	
    73	func New(cfg Config, in Introspector, lim Limiter, logger *slog.Logger, health http.Handler) (http.Handler, error) {
    74		if cfg.IAMURL == nil || cfg.BackendURL == nil {
    75			return nil, errors.New("proxy: upstream URLs are required")
    76		}
    77		if in == nil || lim == nil {
    78			return nil, errors.New("proxy: introspector and limiter are required")
    79		}
    80		if logger == nil {
    81			logger = slog.New(slog.DiscardHandler)
    82		}
    83		if cfg.MaxBodyBytes <= 0 {
    84			cfg.MaxBodyBytes = httpx.DefaultMaxBodyBytes
    85		}
    86		if cfg.UpstreamTimeout <= 0 {
    87			cfg.UpstreamTimeout = DefaultUpstreamTimeout
    88		}
    89		if cfg.DialTimeout <= 0 {
    90			cfg.DialTimeout = DefaultDialTimeout
    91		}
    92		if cfg.Transport == nil {
    93			cfg.Transport = NewTransport(cfg.DialTimeout, cfg.UpstreamTimeout)
    94		}
    95		if health == nil {
    96			health = httpx.NotFoundHandler()
    97		}
    98		h := &Handler{cfg: cfg, introspector: in, limiter: lim, log: logger, health: health}
    99		h.proxies = map[Upstream]http.Handler{
   100			UpstreamIAM:     h.newReverseProxy(UpstreamIAM, cfg.IAMURL),
   101			UpstreamBackend: h.newReverseProxy(UpstreamBackend, cfg.BackendURL),
   102		}
   103		return httpx.Chain(http.HandlerFunc(h.serve), slopLog.RequestIDMiddleware, h.accessLog, httpx.Recover(logger), securityHeaders), nil
   104	}
   105	
   106	func NewTransport(dialTimeout, responseTimeout time.Duration) *http.Transport {
   107		return &http.Transport{
   108			Proxy:                  nil,
   109			DialContext:            (&net.Dialer{Timeout: dialTimeout, KeepAlive: 30 * time.Second}).DialContext,
   110			MaxIdleConns:           256,
   111			MaxIdleConnsPerHost:    128,
   112			IdleConnTimeout:        90 * time.Second,
   113			ResponseHeaderTimeout:  responseTimeout,
   114			ExpectContinueTimeout:  time.Second,
   115			MaxResponseHeaderBytes: 64 << 10,
   116		}
   117	}
   118	
   119	func securityHeaders(next http.Handler) http.Handler {
   120		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   121			hdr := w.Header()
   122			hdr.Set("Cache-Control", "no-store")
   123			hdr.Set("X-Content-Type-Options", "nosniff")
   124			hdr.Set("Referrer-Policy", "no-referrer")
   125			next.ServeHTTP(w, r)
   126		})
   127	}
   128	
   129	func (h *Handler) serve(w http.ResponseWriter, r *http.Request) {
   130		st := stateFrom(r.Context())
   131		if !CanonicalRequestURI(r.RequestURI) {
   132			httpx.WriteError(w, httpx.BadRequest("non-canonical request path"))
   133			return
   134		}
   135		if !CanonicalQuery(r.URL.RawQuery) {
   136			httpx.WriteError(w, httpx.BadRequest("malformed query string"))
   137			return
   138		}
   139		if r.URL.Path == "/healthz" || r.URL.Path == "/readyz" {
   140			h.health.ServeHTTP(w, r)
   141			return
   142		}
   143		up, ok := Route(r.URL.Path)
   144		if !ok {
   145			httpx.WriteError(w, httpx.NotFound("not found"))
   146			return
   147		}
   148		if !allowedMethods[r.Method] {
   149			httpx.MethodNotAllowed().ServeHTTP(w, r)
   150			return
   151		}
   152		st.upstream = up
   153		StripInbound(r.Header)
   154		if r.ContentLength > h.cfg.MaxBodyBytes {
   155			httpx.WriteError(w, httpx.BadRequest("request body is too large"))
   156			return
   157		}
   158		if r.Body != nil && r.Body != http.NoBody {
   159			st.body = &limitedBody{ReadCloser: http.MaxBytesReader(w, r.Body, h.cfg.MaxBodyBytes)}
   160			r.Body = st.body
   161		}
   162		if !IsPublic(r.URL.Path) {
   163			if herr := h.authenticate(r, st); herr != nil {
   164				if herr.Status >= 500 {
   165					h.log.WarnContext(r.Context(), "authentication unavailable", slog.Any("error", herr.Unwrap()))
   166				}
   167				httpx.WriteError(w, herr)
   168				return
   169			}
   170		}
   171		h.proxies[up].ServeHTTP(w, r)
   172	}
   173	
   174	func (h *Handler) authenticate(r *http.Request, st *state) *httpx.Error {
   175		token, fromCookie, ok := Credentials(r)
   176		if !ok {
   177			return httpx.Unauthenticated("authentication required")
   178		}
   179		id, err := h.introspector.Introspect(r.Context(), token)
   180		switch {
   181		case errors.Is(err, iamclient.ErrInactive):
   182			return httpx.Unauthenticated("authentication required")
   183		case err != nil:
   184			return httpx.Unavailable("authentication service unavailable").WithCause(err)
   185		}
   186		st.principal = id.Key()
   187		if allowed, wait := h.limiter.Allow(id.Key()); !allowed {
   188			return httpx.RateLimited(ratelimit.RetryAfterSeconds(wait))
   189		}
   190		if fromCookie && IsMutating(r.Method) {
   191			v := r.Header.Values(CSRFHeader)
   192			if len(v) != 1 || v[0] != "1" {
   193				return httpx.NewError(http.StatusForbidden, httpx.CodeCSRFRequired, "X-SlopDNS-CSRF: 1 header is required")
   194			}
   195		}
   196		st.assertion = id.Assertion
   197		return nil
   198	}
   199	
   200	func Credentials(r *http.Request) (string, bool, bool) {
   201		auth := r.Header.Values("Authorization")
   202		if len(auth) > 1 {
   203			return "", false, false
   204		}
   205		if len(auth) == 1 {
   206			scheme, token, found := strings.Cut(auth[0], " ")
   207			if !found || !strings.EqualFold(scheme, "Bearer") || !validToken(token) || !bearerToken(token) {
   208				return "", false, false
   209			}
   210			return token, false, true
   211		}
   212		cookies := r.CookiesNamed(CookieName)
   213		if len(cookies) != 1 || !validToken(cookies[0].Value) || !strings.HasPrefix(cookies[0].Value, SessionTokenPrefix) {
   214			return "", true, false
   215		}
   216		return cookies[0].Value, true, true
   217	}
   218	
   219	func bearerToken(t string) bool {
   220		return strings.HasPrefix(t, UserTokenPrefix) || strings.HasPrefix(t, ServiceAccountTokenPrefix)
   221	}
   222	
   223	func validToken(t string) bool {
   224		if t == "" || len(t) > MaxTokenLength {
   225			return false
   226		}
   227		for i := 0; i < len(t); i++ {
   228			if t[i] <= ' ' || t[i] >= 0x7f {
   229				return false
   230			}
   231		}
   232		return true
   233	}
   234	
   235	func StripInbound(hdr http.Header) {
   236		hdr.Del(assertion.Header)
   237		hdr.Del("Forwarded")
   238		hdr.Del("X-Forwarded-Host")
   239	}
   240	
   241	var forwardedHeaders = map[Upstream][]string{
   242		UpstreamIAM:     {"Authorization", "Cookie", RealIPHeader, slopLog.RequestIDHeader},
   243		UpstreamBackend: {RealIPHeader, slopLog.RequestIDHeader},
   244	}
   245	
   246	func (h *Handler) newReverseProxy(name Upstream, target *url.URL) http.Handler {
   247		return &httputil.ReverseProxy{
   248			Rewrite: func(pr *httputil.ProxyRequest) {
   249				pr.SetURL(target)
   250				pr.Out.URL.RawQuery = pr.In.URL.RawQuery
   251				for _, k := range forwardedHeaders[name] {
   252					if v := pr.In.Header.Values(k); len(v) > 0 {
   253						pr.Out.Header[k] = append([]string(nil), v...)
   254					}
   255				}
   256				if name != UpstreamIAM {
   257					pr.Out.Header.Del("Authorization")
   258					pr.Out.Header.Del("Cookie")
   259				}
   260				StripInbound(pr.Out.Header)
   261				pr.Out.Header.Del("Upgrade")
   262				pr.Out.Header.Del("Connection")
   263				if st := stateFrom(pr.In.Context()); st.assertion != "" {
   264					pr.Out.Header.Set(assertion.Header, st.assertion)
   265				}
   266			},
   267			Transport: h.cfg.Transport,
   268			ModifyResponse: func(resp *http.Response) error {
   269				for _, k := range []string{assertion.Header, "Cache-Control", "X-Content-Type-Options", "Referrer-Policy", slopLog.RequestIDHeader, "Server"} {
   270					resp.Header.Del(k)
   271				}
   272				return nil
   273			},
   274			ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
   275				st := stateFrom(r.Context())
   276				if st.body != nil && st.body.exceeded.Load() {
   277					httpx.WriteError(w, httpx.BadRequest("request body is too large"))
   278					return
   279				}
   280				if r.Context().Err() != nil {
   281					h.log.DebugContext(r.Context(), "client went away", slog.String("upstream", string(name)))
   282					httpx.WriteError(w, httpx.NewError(http.StatusBadGateway, httpx.CodeUnavailable, "upstream service unavailable"))
   283					return
   284				}
   285				h.log.WarnContext(r.Context(), "upstream request failed", slog.String("upstream", string(name)), slog.Any("error", err))
   286				httpx.WriteError(w, httpx.NewError(http.StatusBadGateway, httpx.CodeUnavailable, "upstream service unavailable"))
   287			},
   288			ErrorLog: slog.NewLogLogger(h.log.Handler(), slog.LevelWarn),
   289		}
   290	}
   291	
   292	type limitedBody struct {
   293		io.ReadCloser
   294		exceeded atomic.Bool
   295	}
   296	
   297	func (l *limitedBody) Read(p []byte) (int, error) {
   298		n, err := l.ReadCloser.Read(p)
   299		var mbe *http.MaxBytesError
   300		if err != nil && errors.As(err, &mbe) {
   301			l.exceeded.Store(true)
   302		}
   303		return n, err
   304	}
   305	
   306	type recorder struct {
   307		http.ResponseWriter
   308		status int
   309		bytes  int64
   310	}
   311	
   312	func (r *recorder) WriteHeader(code int) {
   313		if r.status == 0 && code >= 200 {
   314			r.status = code
   315		}
   316		r.ResponseWriter.WriteHeader(code)
   317	}
   318	
   319	func (r *recorder) Write(b []byte) (int, error) {
   320		if r.status == 0 {
   321			r.status = http.StatusOK
   322		}
   323		n, err := r.ResponseWriter.Write(b)
   324		r.bytes += int64(n)
   325		return n, err
   326	}
   327	
   328	func (r *recorder) Flush() {
   329		if f, ok := r.ResponseWriter.(http.Flusher); ok {
   330			f.Flush()
   331		}
   332	}
   333	
   334	func (r *recorder) Unwrap() http.ResponseWriter {
   335		return r.ResponseWriter
   336	}
   337	
   338	func (h *Handler) accessLog(next http.Handler) http.Handler {
   339		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   340			st := &state{}
   341			r = r.WithContext(context.WithValue(r.Context(), stateKey{}, st))
   342			if r.URL.Path == "/healthz" || r.URL.Path == "/readyz" {
   343				next.ServeHTTP(w, r)
   344				return
   345			}
   346			start := time.Now()
   347			realIP := RealIP(r.Header)
   348			rec := &recorder{ResponseWriter: w}
   349			defer func() {
   350				status := rec.status
   351				if status == 0 {
   352					status = http.StatusOK
   353				}
   354				level := slog.LevelInfo
   355				if status >= 500 {
   356					level = slog.LevelError
   357				}
   358				path := r.URL.EscapedPath()
   359				if len(path) > maxLoggedPath {
   360					path = path[:maxLoggedPath]
   361				}
   362				h.log.LogAttrs(r.Context(), level, "http request",
   363					slog.String("method", r.Method),
   364					slog.String("path", path),
   365					slog.Int("status", status),
   366					slog.Int64("bytes", rec.bytes),
   367					slog.Duration("duration", time.Since(start)),
   368					slog.String("real_ip", realIP),
   369					slog.String("remote", r.RemoteAddr),
   370					slog.String("upstream", string(st.upstream)),
   371					slog.String("principal", st.principal),
   372				)
   373			}()
   374			next.ServeHTTP(rec, r)
   375		})
   376	}
   377	
   378	func RealIP(hdr http.Header) string {
   379		v := hdr.Get(RealIPHeader)
   380		if v == "" {
   381			return ""
   382		}
   383		addr, err := netip.ParseAddr(strings.TrimSpace(v))
   384		if err != nil {
   385			return "invalid"
   386		}
   387		return addr.String()
   388	}
===web/gateway/internal/proxy/routes.go
     1	package proxy
     2	
     3	import (
     4		"net/http"
     5		"strings"
     6	)
     7	
     8	const (
     9		APIPrefix    = "/api/v1/"
    10		CookieName   = "slopdns_session"
    11		CSRFHeader   = "X-SlopDNS-CSRF"
    12		RealIPHeader = "X-Real-IP"
    13	
    14		SessionTokenPrefix        = "sdses_"
    15		UserTokenPrefix           = "sdpat_"
    16		ServiceAccountTokenPrefix = "sdsat_"
    17	)
    18	
    19	type Upstream string
    20	
    21	const (
    22		UpstreamIAM     Upstream = "iam"
    23		UpstreamBackend Upstream = "backend"
    24	)
    25	
    26	var routeTable = map[string]Upstream{
    27		"auth":             UpstreamIAM,
    28		"users":            UpstreamIAM,
    29		"service-accounts": UpstreamIAM,
    30		"role-bindings":    UpstreamIAM,
    31		"orgs":             UpstreamBackend,
    32		"zones":            UpstreamBackend,
    33		"records":          UpstreamBackend,
    34		"zone-transfers":   UpstreamBackend,
    35		"invitations":      UpstreamBackend,
    36	}
    37	
    38	var publicPaths = map[string]bool{
    39		APIPrefix + "auth/register":   true,
    40		APIPrefix + "auth/login":      true,
    41		APIPrefix + "auth/login/totp": true,
    42	}
    43	
    44	var allowedMethods = map[string]bool{
    45		http.MethodGet:     true,
    46		http.MethodHead:    true,
    47		http.MethodPost:    true,
    48		http.MethodPut:     true,
    49		http.MethodPatch:   true,
    50		http.MethodDelete:  true,
    51		http.MethodOptions: true,
    52	}
    53	
    54	func Route(path string) (Upstream, bool) {
    55		rest, ok := strings.CutPrefix(path, APIPrefix)
    56		if !ok {
    57			return "", false
    58		}
    59		first, _, _ := strings.Cut(rest, "/")
    60		u, ok := routeTable[first]
    61		return u, ok
    62	}
    63	
    64	func IsPublic(path string) bool {
    65		return publicPaths[path]
    66	}
    67	
    68	func IsMutating(method string) bool {
    69		switch method {
    70		case http.MethodGet, http.MethodHead, http.MethodOptions:
    71			return false
    72		}
    73		return true
    74	}
    75	
    76	func CanonicalRequestURI(requestURI string) bool {
    77		path, _, _ := strings.Cut(requestURI, "?")
    78		if path == "" || path[0] != '/' {
    79			return false
    80		}
    81		for i := 0; i < len(path); i++ {
    82			if !pathByte(path[i]) {
    83				return false
    84			}
    85		}
    86		if strings.Contains(path, "//") {
    87			return false
    88		}
    89		for _, seg := range strings.Split(path[1:], "/") {
    90			if seg == "." || seg == ".." {
    91				return false
    92			}
    93		}
    94		return true
    95	}
    96	
    97	func pathByte(c byte) bool {
    98		switch {
    99		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
   100			return true
   101		}
   102		return strings.IndexByte("-._~!$&'()*+,;=:@/", c) >= 0
   103	}
   104	
   105	func CanonicalQuery(raw string) bool {
   106		for i := 0; i < len(raw); i++ {
   107			switch raw[i] {
   108			case ';':
   109				return false
   110			case '%':
   111				if i+2 >= len(raw) || !isHex(raw[i+1]) || !isHex(raw[i+2]) {
   112					return false
   113				}
   114				i += 2
   115			}
   116		}
   117		return true
   118	}
   119	
   120	func isHex(c byte) bool {
   121		return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
   122	}
