     1	package ratelimit
     2	
     3	import (
     4		"math"
     5		"sync"
     6		"time"
     7	)
     8	
     9	const DefaultSweepInterval = time.Minute
    10	
    11	type bucket struct {
    12		tokens float64
    13		last   time.Time
    14	}
    15	
    16	type Limiter struct {
    17		mu         sync.Mutex
    18		rate       float64
    19		burst      float64
    20		idle       time.Duration
    21		sweepEvery time.Duration
    22		lastSweep  time.Time
    23		now        func() time.Time
    24		buckets    map[string]*bucket
    25	}
    26	
    27	func New(rps float64, burst int, now func() time.Time) *Limiter {
    28		if rps <= 0 {
    29			rps = 1
    30		}
    31		if burst < 1 {
    32			burst = 1
    33		}
    34		if now == nil {
    35			now = time.Now
    36		}
    37		refill := time.Duration(math.Ceil(float64(burst) / rps * float64(time.Second)))
    38		return &Limiter{
    39			rate:       rps,
    40			burst:      float64(burst),
    41			idle:       refill + time.Second,
    42			sweepEvery: DefaultSweepInterval,
    43			lastSweep:  now(),
    44			now:        now,
    45			buckets:    map[string]*bucket{},
    46		}
    47	}
    48	
    49	func (l *Limiter) Allow(key string) (bool, time.Duration) {
    50		l.mu.Lock()
    51		defer l.mu.Unlock()
    52		now := l.now()
    53		l.sweepLocked(now)
    54		b, ok := l.buckets[key]
    55		if !ok {
    56			b = &bucket{tokens: l.burst, last: now}
    57			l.buckets[key] = b
    58		}
    59		if elapsed := now.Sub(b.last); elapsed > 0 {
    60			b.tokens = math.Min(l.burst, b.tokens+elapsed.Seconds()*l.rate)
    61		}
    62		b.last = now
    63		if b.tokens >= 1 {
    64			b.tokens--
    65			return true, 0
    66		}
    67		wait := time.Duration((1 - b.tokens) / l.rate * float64(time.Second))
    68		return false, wait
    69	}
    70	
    71	func (l *Limiter) sweepLocked(now time.Time) {
    72		if now.Sub(l.lastSweep) < l.sweepEvery {
    73			return
    74		}
    75		l.lastSweep = now
    76		for k, b := range l.buckets {
    77			if now.Sub(b.last) >= l.idle {
    78				delete(l.buckets, k)
    79			}
    80		}
    81	}
    82	
    83	func (l *Limiter) Len() int {
    84		l.mu.Lock()
    85		defer l.mu.Unlock()
    86		return len(l.buckets)
    87	}
    88	
    89	func RetryAfterSeconds(wait time.Duration) int {
    90		s := int(math.Ceil(wait.Seconds()))
    91		if s < 1 {
    92			return 1
    93		}
    94		return s
    95	}
