    49	func LoadConfig(env *config.Env) (Config, error) {
    50		c := Config{Base: app.LoadBase(env)}
    51		c.PKIDir = env.String("PKI_DIR", "/pki")
    52		c.IAMGRPCAddr = env.Addr("IAM_GRPC_ADDR", DefaultIAMGRPCAddr)
    53		c.IAMServerName = env.String("IAM_GRPC_SERVER_NAME", "")
    54		c.IAMHTTPURL = upstreamURL(env, "IAM_HTTP_URL", DefaultIAMHTTPURL)
    55		c.BackendHTTPURL = upstreamURL(env, "BACKEND_HTTP_URL", DefaultBackendHTTPURL)
    56		c.RateLimitRPS = env.Float("RATE_LIMIT_RPS", DefaultRateLimitRPS, 0.01, 1e6)
    57		c.RateLimitBurst = env.Int("RATE_LIMIT_BURST", DefaultRateLimitBurst, 1, 1_000_000)
    58		c.MaxBodyBytes = int64(env.Int("MAX_BODY_BYTES", int(httpx.DefaultMaxBodyBytes), 1024, 64<<20))
    59		c.IntrospectTimeout = env.Duration("INTROSPECT_TIMEOUT", iamclient.DefaultTimeout, 100*time.Millisecond, 30*time.Second)
    60		c.UpstreamTimeout = env.Duration("UPSTREAM_TIMEOUT", proxy.DefaultUpstreamTimeout, time.Second, 5*time.Minute)
    61		return c, env.Err()
