    63	
    64	func upstreamURL(env *config.Env, name, def string) *url.URL {
    65		raw := env.URL(name, def, true, "http")
    66		u, err := url.Parse(raw)
    67		if err != nil || u.Host == "" {
    68			u, _ = url.Parse(def)
    69			return u
    70		}
    71		if (u.Path != "" && u.Path != "/") || u.RawQuery != "" || u.Fragment != "" || u.User != nil {
    72			env.Fail(name, "must be scheme://host:port without path, query or credentials")
    73			u, _ = url.Parse(def)
    74			return u
    75		}
    76		u.Path = ""
    77		return u
    78	}
