     1	package iamclient
     2	
     3	import (
     4		"context"
     5		"errors"
     6		"fmt"
     7		"net"
     8		"strings"
     9		"time"
    10	
    11		"google.golang.org/grpc"
    12		"google.golang.org/grpc/codes"
    13		"google.golang.org/grpc/credentials"
    14		"google.golang.org/grpc/status"
    15	
    16		iamv1 "slopdns/web/gen/slopdns/iam/v1"
    17		"slopdns/web/pkg/assertion"
    18		"slopdns/web/pkg/mtls"
    19	)
    20	
    21	const DefaultTimeout = 3 * time.Second
    22	
    23	var (
    24		ErrInactive    = errors.New("token is not active")
    25		ErrUnavailable = errors.New("identity service unavailable")
    26	)
    27	
    28	type Identity struct {
    29		Type      assertion.PrincipalType
    30		ID        string
    31		Name      string
    32		OrgID     string
    33		Assertion string
    34	}
    35	
    36	func (i Identity) Key() string {
    37		return string(i.Type) + ":" + i.ID
    38	}
    39	
    40	type Client struct {
    41		rpc     iamv1.IamServiceClient
    42		timeout time.Duration
    43	}
    44	
    45	func New(rpc iamv1.IamServiceClient, timeout time.Duration) *Client {
    46		if timeout <= 0 {
    47			timeout = DefaultTimeout
    48		}
    49		return &Client{rpc: rpc, timeout: timeout}
    50	}
    51	
    52	func Dial(addr, serverName string, m *mtls.Material) (*grpc.ClientConn, error) {
    53		if serverName == "" {
    54			host, _, err := net.SplitHostPort(addr)
    55			if err != nil {
    56				return nil, fmt.Errorf("iam address: %w", err)
    57			}
    58			serverName = host
    59		}
    60		tlsCfg, err := mtls.ClientConfig(m, serverName, mtls.AllowURIs(mtls.ServiceURI("iam")))
    61		if err != nil {
    62			return nil, err
    63		}
    64		return grpc.NewClient(addr, grpc.WithTransportCredentials(credentials.NewTLS(tlsCfg)))
    65	}
    66	
    67	func (c *Client) Introspect(ctx context.Context, token string) (Identity, error) {
    68		ctx, cancel := context.WithTimeout(ctx, c.timeout)
    69		defer cancel()
    70		resp, err := c.rpc.Introspect(ctx, &iamv1.IntrospectRequest{Token: token})
    71		if err != nil {
    72			switch status.Code(err) {
    73			case codes.Unauthenticated, codes.InvalidArgument, codes.NotFound:
    74				return Identity{}, ErrInactive
    75			}
    76			return Identity{}, fmt.Errorf("%w: %w", ErrUnavailable, err)
    77		}
    78		if !resp.GetActive() {
    79			return Identity{}, ErrInactive
    80		}
    81		id, err := identityFrom(resp)
    82		if err != nil {
    83			return Identity{}, fmt.Errorf("%w: %w", ErrUnavailable, err)
    84		}
    85		return id, nil
    86	}
    87	
    88	func (c *Client) Ping(ctx context.Context) error {
    89		ctx, cancel := context.WithTimeout(ctx, c.timeout)
    90		defer cancel()
    91		resp, err := c.rpc.Introspect(ctx, &iamv1.IntrospectRequest{})
    92		if err != nil {
    93			return err
    94		}
    95		if resp.GetActive() {
    96			return errors.New("empty token reported active")
    97		}
    98		return nil
    99	}
   100	
   101	func identityFrom(resp *iamv1.IntrospectResponse) (Identity, error) {
   102		id := Identity{
   103			ID:        resp.GetPrincipal().GetId(),
   104			Name:      resp.GetPrincipalName(),
   105			OrgID:     resp.GetOrgId(),
   106			Assertion: resp.GetAssertion(),
   107		}
   108		switch resp.GetPrincipal().GetType() {
   109		case iamv1.PrincipalType_PRINCIPAL_TYPE_USER:
   110			id.Type = assertion.PrincipalUser
   111		case iamv1.PrincipalType_PRINCIPAL_TYPE_SERVICE_ACCOUNT:
   112			id.Type = assertion.PrincipalServiceAccount
   113		default:
   114			return Identity{}, errors.New("introspection returned no principal type")
   115		}
   116		if !validID(id.ID) {
   117			return Identity{}, errors.New("introspection returned an invalid principal id")
   118		}
   119		if !validAssertion(id.Assertion) {
   120			return Identity{}, errors.New("introspection returned an invalid assertion")
   121		}
   122		return id, nil
   123	}
   124	
   125	func validID(s string) bool {
   126		if s == "" || len(s) > 64 {
   127			return false
   128		}
   129		for i := 0; i < len(s); i++ {
   130			c := s[i]
   131			if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != '-' {
   132				return false
   133			}
   134		}
   135		return true
   136	}
   137	
   138	func validAssertion(s string) bool {
   139		if s == "" || len(s) > assertion.MaxLength || strings.Count(s, ".") != 2 {
   140			return false
   141		}
   142		for i := 0; i < len(s); i++ {
   143			c := s[i]
   144			if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != '-' && c != '_' && c != '.' {
   145				return false
   146			}
   147		}
   148		return true
   149	}

