   235	func StripInbound(hdr http.Header) {
   236		hdr.Del(assertion.Header)
   237		hdr.Del("Forwarded")
   238		hdr.Del("X-Forwarded-Host")
   239	}
   240	
   241	var forwardedHeaders = map[Upstream][]string{
   242		UpstreamIAM:     {"Authorization", "Cookie", RealIPHeader, slopLog.RequestIDHeader},
   243		UpstreamBackend: {RealIPHeader, slopLog.RequestIDHeader},
   244	}
