   246	func (h *Handler) newReverseProxy(name Upstream, target *url.URL) http.Handler {
   247		return &httputil.ReverseProxy{
   248			Rewrite: func(pr *httputil.ProxyRequest) {
   249				pr.SetURL(target)
   250				pr.Out.URL.RawQuery = pr.In.URL.RawQuery
   251				for _, k := range forwardedHeaders[name] {
   252					if v := pr.In.Header.Values(k); len(v) > 0 {
   253						pr.Out.Header[k] = append([]string(nil), v...)
   254					}
   255				}
   256				if name != UpstreamIAM {
   257					pr.Out.Header.Del("Authorization")
   258					pr.Out.Header.Del("Cookie")
   259				}
   260				StripInbound(pr.Out.Header)
   261				pr.Out.Header.Del("Upgrade")
   262				pr.Out.Header.Del("Connection")
   263				if st := stateFrom(pr.In.Context()); st.assertion != "" {
   264					pr.Out.Header.Set(assertion.Header, st.assertion)
   265				}
   266			},
   267			Transport: h.cfg.Transport,
   268			ModifyResponse: func(resp *http.Response) error {
   269				for _, k := range []string{assertion.Header, "Cache-Control", "X-Content-Type-Options", "Referrer-Policy", slopLog.RequestIDHeader, "Server"} {
   270					resp.Header.Del(k)
   271				}
   272				return nil
   273			},
   274			ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
   275				st := stateFrom(r.Context())
   276				if st.body != nil && st.body.exceeded.Load() {
   277					httpx.WriteError(w, httpx.BadRequest("request body is too large"))
   278					return
   279				}
   280				if r.Context().Err() != nil {
   281					h.log.DebugContext(r.Context(), "client went away", slog.String("upstream", string(name)))
   282					httpx.WriteError(w, httpx.NewError(http.StatusBadGateway, httpx.CodeUnavailable, "upstream service unavailable"))
   283					return
   284				}
   285				h.log.WarnContext(r.Context(), "upstream request failed", slog.String("upstream", string(name)), slog.Any("error", err))
   286				httpx.WriteError(w, httpx.NewError(http.StatusBadGateway, httpx.CodeUnavailable, "upstream service unavailable"))
   287			},
   288			ErrorLog: slog.NewLogLogger(h.log.Handler(), slog.LevelWarn),
   289		}
   290	}
