    54	func Route(path string) (Upstream, bool) {
    55		rest, ok := strings.CutPrefix(path, APIPrefix)
    56		if !ok {
    57			return "", false
    58		}
    59		first, _, _ := strings.Cut(rest, "/")
    60		u, ok := routeTable[first]
    61		return u, ok
    62	}
    63	
    64	func IsPublic(path string) bool {
    65		return publicPaths[path]
    66	}
    67	
    68	func IsMutating(method string) bool {
    69		switch method {
    70		case http.MethodGet, http.MethodHead, http.MethodOptions:
    71			return false
    72		}
    73		return true
    74	}
    75	
    76	func CanonicalRequestURI(requestURI string) bool {
    77		path, _, _ := strings.Cut(requestURI, "?")
    78		if path == "" || path[0] != '/' {
    79			return false
    80		}
    81		for i := 0; i < len(path); i++ {
    82			if !pathByte(path[i]) {
    83				return false
    84			}
    85		}
    86		if strings.Contains(path, "//") {
    87			return false
    88		}
    89		for _, seg := range strings.Split(path[1:], "/") {
    90			if seg == "." || seg == ".." {
    91				return false
    92			}
    93		}
    94		return true
    95	}
    96	
    97	func pathByte(c byte) bool {
    98		switch {
    99		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
   100			return true
   101		}
   102		return strings.IndexByte("-._~!$&'()*+,;=:@/", c) >= 0
   103	}
   104	
   105	func CanonicalQuery(raw string) bool {
   106		for i := 0; i < len(raw); i++ {
   107			switch raw[i] {
   108			case ';':
   109				return false
   110			case '%':
   111				if i+2 >= len(raw) || !isHex(raw[i+1]) || !isHex(raw[i+2]) {
   112					return false
   113				}
   114				i += 2
   115			}
   116		}
   117		return true
   118	}
   119	
   120	func isHex(c byte) bool {
   121		return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
   122	}
