    85	
    86	func Build(cfg Config, logger *slog.Logger, rpc iamv1.IamServiceClient) (*Deps, error) {
    87		client := iamclient.New(rpc, cfg.IntrospectTimeout)
    88		h := health.New(logger, 0)
    89		probe := &http.Client{Transport: &http.Transport{Proxy: nil, DisableKeepAlives: true}}
    90		iamReady := cfg.IAMHTTPURL.JoinPath("/readyz").String()
    91		backendReady := cfg.BackendHTTPURL.JoinPath("/readyz").String()
    92		h.Register("iam", func(ctx context.Context) error {
    93			if err := client.Ping(ctx); err != nil {
    94				return fmt.Errorf("introspect: %w", err)
    95			}
    96			return probeURL(ctx, probe, iamReady)
    97		})
    98		h.RegisterDetails("backend", func() any {
    99			ctx, cancel := context.WithTimeout(context.Background(), backendProbeTimeout)
   100			defer cancel()
   101			if err := probeURL(ctx, probe, backendReady); err != nil {
   102				return health.StatusUnavailable
   103			}
   104			return health.StatusOK
   105		})
   106		mux := http.NewServeMux()
   107		h.Mount(mux)
   108		handler, err := proxy.New(proxy.Config{
   109			IAMURL:          cfg.IAMHTTPURL,
   110			BackendURL:      cfg.BackendHTTPURL,
   111			MaxBodyBytes:    cfg.MaxBodyBytes,
   112			UpstreamTimeout: cfg.UpstreamTimeout,
   113		}, client, ratelimit.New(cfg.RateLimitRPS, cfg.RateLimitBurst, nil), logger, mux)
   114		if err != nil {
   115			return nil, err
   116		}
   117		return &Deps{Introspector: client, Health: h, Handler: handler}, nil
   118	}
   119	
   120	func probeURL(ctx context.Context, c *http.Client, u string) error {
   121		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
   122		if err != nil {
   123			return err
   124		}
   125		resp, err := c.Do(req)
   126		if err != nil {
   127			return err
   128		}
   129		defer func() { _ = resp.Body.Close() }()
   130		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16))
   131		if resp.StatusCode != http.StatusOK {
   132			return fmt.Errorf("%s returned HTTP %d", u, resp.StatusCode)
   133		}
   134		return nil
   135	}
