   137	func Serve(ctx context.Context, cfg Config, logger *slog.Logger) error {
   138		material, err := mtls.Load(mtls.FilesIn(cfg.PKIDir, Name))
   139		if err != nil {
   140			return fmt.Errorf("load mTLS material: %w", err)
   141		}
   142		conn, err := iamclient.Dial(cfg.IAMGRPCAddr, cfg.IAMServerName, material)
   143		if err != nil {
   144			return fmt.Errorf("dial iam: %w", err)
   145		}
   146		defer func() { _ = conn.Close() }()
   147		deps, err := Build(cfg, logger, iamv1.NewIamServiceClient(conn))
   148		if err != nil {
   149			return err
   150		}
   151		return app.ListenAndServe(ctx, logger, cfg.HTTPAddr, deps.Handler)
   152	}
