   125	func validID(s string) bool {
   126		if s == "" || len(s) > 64 {
   127			return false
   128		}
   129		for i := 0; i < len(s); i++ {
   130			c := s[i]
   131			if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != '-' {
   132				return false
   133			}
   134		}
   135		return true
   136	}
   137	
   138	func validAssertion(s string) bool {
   139		if s == "" || len(s) > assertion.MaxLength || strings.Count(s, ".") != 2 {
   140			return false
   141		}
   142		for i := 0; i < len(s); i++ {
   143			c := s[i]
   144			if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != '-' && c != '_' && c != '.' {
   145				return false
   146			}
   147		}
   148		return true
   149	}

