   197		if err != nil {
   198			s.log.WarnContext(ctx, "sync stream rejected", slog.String("reason", "peer identity"), slog.Any("error", err))
   199			return status.Error(codes.PermissionDenied, "client certificate identity is not allowed")
   200		}
   201		key, ok := s.opts.NodeKeys[node]
   202		if !ok {
   203			s.log.WarnContext(ctx, "sync stream rejected", slog.String("node", node), slog.String("reason", "node not in DNS_NODE_IDS"))
   204			return status.Error(codes.PermissionDenied, "node is not allowed")
   205		}
   206		logger := s.log.With(slog.String("node", node), slog.String("peer", addr))
   207		in := make(chan *syncv1.ClientFrame, 1)
   208		go func() {
   209			for {
   210				f, err := stream.Recv()
   211				if err != nil {
   212					if errors.Is(err, io.EOF) {
   213						cancel(errClosedSend)
   214					} else {
   215						cancel(err)
   216					}
   217					return
   218				}
   219				select {
   220				case in <- f:
   221				case <-ctx.Done():
   222					return
   223				}
   224			}
   225		}()
   226		hello, err := s.awaitHello(ctx, in, node, key)
   227		if err != nil {
   228			logger.WarnContext(ctx, "sync handshake failed", slog.Any("error", err))
   229			return finalStatus(err)
   230		}
   231		sess, err := s.open(ctx, cancel, node, addr, key, logger)
   232		if err != nil {
   233			return finalStatus(err)
   234		}
   235		defer s.closeSession(sess)
   236		go sess.sendLoop(stream)
   237		err = sess.serve(hello, in)
   238		if errors.Is(err, errClosedSend) {
   239			sess.log.InfoContext(ctx, "sync session closed by client", sess.attrs()...)
   240			return nil
   241		}
   242		sess.log.InfoContext(ctx, "sync session ended", append(sess.attrs(), slog.Any("reason", err))...)
   243		return finalStatus(err)
   244	}
