   262	func (s *Server) awaitHello(ctx context.Context, in <-chan *syncv1.ClientFrame, node string, key ed25519.PublicKey) (*syncv1.Hello, error) {
   263		timer := time.NewTimer(s.opts.HelloTimeout)
   264		defer timer.Stop()
   265		var f *syncv1.ClientFrame
   266		select {
   267		case f = <-in:
   268		case <-timer.C:
   269			return nil, status.Error(codes.DeadlineExceeded, "no hello received")
   270		case <-ctx.Done():
   271			return nil, context.Cause(ctx)
   272		}
   273		kind, signed, err := syncproto.UnwrapClient(f)
   274		if err != nil || kind != syncv1.FrameKind_FRAME_KIND_HELLO {
   275			return nil, status.Error(codes.InvalidArgument, "first frame must be hello")
   276		}
   277		hello := &syncv1.Hello{}
   278		if err := syncproto.Open(key, kind, syncproto.ZeroSession(), signed, hello); err != nil {
   279			if errors.Is(err, syncproto.ErrBadSignature) {
   280				return nil, status.Error(codes.Unauthenticated, "hello signature is invalid")
   281			}
   282			return nil, status.Error(codes.InvalidArgument, "hello payload is malformed")
   283		}
   284		if hello.GetNodeId() != node {
   285			return nil, status.Errorf(codes.PermissionDenied, "hello node_id %q does not match the certificate", hello.GetNodeId())
   286		}
   287		if len(hello.GetNonce()) != syncproto.NonceSize {
   288			return nil, status.Error(codes.InvalidArgument, "hello nonce must be 16 bytes")
   289		}
   290		if hello.GetProtoVersion() != syncproto.ProtoVersion {
   291			return nil, status.Errorf(codes.FailedPrecondition, "unsupported proto_version %d, want %d", hello.GetProtoVersion(), syncproto.ProtoVersion)
   292		}
   293		return hello, nil
   294	}
