   393				live[sess.node] = sess
   394			}
   395		}
   396		out := make([]NodeStatus, 0, len(s.nodes))
   397		for node, st := range s.nodes {
   398			ns := NodeStatus{Node: node, AckedRevision: st.acked, Sessions: st.sessions, Snapshots: st.snapshots, ResyncReason: st.resyncReason}
