   400				t := st.resyncAt
   401				ns.ResyncAt = &t
   402			}
   403			if !st.lastAck.IsZero() {
   404				t := st.lastAck
   405				ns.LastAckAt = &t
   406			}
   407			if sess, ok := live[node]; ok {
   408				t := sess.started
   409				ns.Connected = true
   410				ns.Session = hex.EncodeToString(sess.id)
