    45	function buildUrl(path: string, query: Record<string, QueryValue> | undefined): URL {
    46	  const url = new URL(API_PREFIX + path, window.location.origin)
    47	  for (const [key, value] of Object.entries(query ?? {})) {
    48	    if (value !== undefined && value !== null && value !== '') {
    49	      url.searchParams.set(key, String(value))
    50	    }
    51	  }
    52	  return url
    53	}
    54	
    55	async function readJson(response: Response): Promise<unknown> {
    56	  const text = await response.text()
    57	  if (text === '') {
    58	    return undefined
    59	  }
    60	  try {
    61	    return JSON.parse(text) as unknown
    62	  } catch {
    63	    return undefined
    64	  }
    65	}
    66	
    67	function isErrorBody(value: unknown): value is ApiErrorBody {
    68	  if (typeof value !== 'object' || value === null || !('error' in value)) {
    69	    return false
    70	  }
    71	  const inner = (value as { error: unknown }).error
    72	  return typeof inner === 'object' && inner !== null && 'code' in inner
    73	}
