    75	function parseRetryAfter(header: string | null): number | undefined {
    76	  if (header === null) {
    77	    return undefined
    78	  }
    79	  const seconds = Number.parseInt(header, 10)
    80	  return Number.isFinite(seconds) && seconds > 0 ? seconds : undefined
