    41			if name[i] == '.' {
    42				n := i - start
    43				if n == 0 || n > maxLabel {
    44					return false
    45				}
    46				wire += n + 1
    47				start = i + 1
    48				continue
    49			}
    50			if !canonicalChar(name[i]) {
    51				return false
    52			}
    53		}
