   170		for _, set := range z.GetRrsets() {
   171			if err := ValidateRRSet(z.GetApex(), set); err != nil {
   172				return err
   173			}
   174			k := setKey{set.GetOwner(), set.GetType(), set.GetRrClass()}
   175			if seen[k] {
   176				return invalidf("duplicate rrset %s type %d in zone %s", k.owner, k.typ, z.GetApex())
   177			}
   178			seen[k] = true
