    14	const (
    15		TypeGPT       uint16 = 65280
    16		GPTMnemonic          = "GPT"
    17		GPTMaxTextLen        = 40
    18	)
    19	
    20	var (
    21		errGPTTooLong   = errors.New("GPT text is longer than 40 octets")
    22		errGPTTruncated = errors.New("GPT RDATA is truncated")
    23		errGPTUTF8      = errors.New("GPT text is not valid UTF-8")
    24		errGPTTokens    = errors.New("GPT RDATA must be a single character-string")
    25	)
    26	
    27	type GPT struct {
    28		Text string
    29	}
    30	
    31	func init() {
    32		dns.PrivateHandle(GPTMnemonic, TypeGPT, func() dns.PrivateRdata { return new(GPT) })
    33	}
    34	
    35	func (g *GPT) Len() int {
    36		return 1 + len(g.Text)
    37	}
    38	
    39	func (g *GPT) String() string {
    40		return quoteCharString(g.Text)
    41	}
    42	
    43	func (g *GPT) Parse(tokens []string) error {
    44		if len(tokens) > 1 {
    45			return errGPTTokens
    46		}
    47		text := ""
    48		if len(tokens) == 1 {
    49			text = unescape(tokens[0])
    50		}
    51		if len(text) > GPTMaxTextLen {
    52			return errGPTTooLong
    53		}
    54		if !utf8.ValidString(text) {
    55			return errGPTUTF8
    56		}
    57		g.Text = text
    58		return nil
    59	}
    60	
    61	func (g *GPT) Pack(buf []byte) (int, error) {
    62		if len(g.Text) > GPTMaxTextLen {
    63			return 0, errGPTTooLong
    64		}
    65		if len(buf) < 1+len(g.Text) {
    66			return 0, dns.ErrBuf
    67		}
    68		buf[0] = conv.U8(int64(len(g.Text)))
    69		copy(buf[1:], g.Text)
    70		return 1 + len(g.Text), nil
    71	}
    72	
    73	func (g *GPT) Unpack(buf []byte) (int, error) {
    74		if len(buf) < 1 {
    75			return 0, errGPTTruncated
    76		}
    77		n := int(buf[0])
    78		if n > GPTMaxTextLen {
    79			return 0, errGPTTooLong
    80		}
    81		if len(buf) < 1+n {
    82			return 0, errGPTTruncated
    83		}
    84		g.Text = string(buf[1 : 1+n])
    85		return 1 + n, nil
    86	}
    87	
    88	func (g *GPT) Copy(dst dns.PrivateRdata) error {
    89		d, ok := dst.(*GPT)
    90		if !ok {
    91			return dns.ErrRdata
    92		}
    93		d.Text = g.Text
    94		return nil
    95	}
