    97	func quoteCharString(s string) string {
    98		var b strings.Builder
    99		b.WriteByte('"')
   100		for i := 0; i < len(s); i++ {
   101			c := s[i]
   102			switch {
   103			case c == '"' || c == '\\':
   104				b.WriteByte('\\')
   105				b.WriteByte(c)
   106			case c < 0x20 || c == 0x7f:
   107				b.WriteByte('\\')
   108				d := strconv.Itoa(int(c))
   109				b.WriteString(strings.Repeat("0", 3-len(d)))
   110				b.WriteString(d)
   111			default:
   112				b.WriteByte(c)
   113			}
   114		}
   115		b.WriteByte('"')
   116		return b.String()
   117	}
   118	
   119	func unescape(s string) string {
   120		if !strings.Contains(s, "\\") {
   121			return s
   122		}
   123		out := make([]byte, 0, len(s))
   124		for i := 0; i < len(s); i++ {
   125			c := s[i]
   126			if c != '\\' || i+1 >= len(s) {
   127				out = append(out, c)
   128				continue
   129			}
   130			if i+3 < len(s) && isDigit(s[i+1]) && isDigit(s[i+2]) && isDigit(s[i+3]) {
   131				v := int(s[i+1]-'0')*100 + int(s[i+2]-'0')*10 + int(s[i+3]-'0')
   132				if v <= 255 {
   133					out = append(out, conv.U8(int64(v)))
   134					i += 3
   135					continue
   136				}
   137			}
   138			out = append(out, s[i+1])
   139			i++
   140		}
   141		return string(out)
   142	}
   143	
   144	func isDigit(c byte) bool {
   145		return c >= '0' && c <= '9'
   146	}
   147	
   148	func escapeForPack(s string) string {
   149		return strings.ReplaceAll(s, "\\", "\\\\")
   150	}
