   164	func (r *rawRdata) Pack(buf []byte) (int, error) {
   165		if len(buf) < len(r.data) {
   166			return 0, dns.ErrBuf
   167		}
   168		return copy(buf, r.data), nil
   169	}
   170	
   171	func (r *rawRdata) Unpack(buf []byte) (int, error) {
   172		r.data = append([]byte(nil), buf...)
   173		return len(buf), nil
   174	}
   175	
   176	func (r *rawRdata) Copy(dst dns.PrivateRdata) error {
   177		d, ok := dst.(*rawRdata)
   178		if !ok {
   179			return dns.ErrRdata
   180		}
   181		d.data = append([]byte(nil), r.data...)
