   187	}
   188	
   189	func quoteOctets(s string) string {
   190		var b strings.Builder
   191		b.WriteByte('"')
   192		for i := 0; i < len(s); i++ {
   193			if s[i] == '"' || s[i] == '\\' {
   194				b.WriteByte('\\')
   195			}
   196			b.WriteByte(s[i])
   197		}
   198		b.WriteByte('"')
   199		return b.String()
   200	}
     1	package dnsdata
     2	
     3	import (
     4		"errors"
     5		"fmt"
     6		"strings"
     7	
     8		syncv1 "slopdns/web/gen/slopdns/sync/v1"
     9	)
    10	
    11	const (
    12		TypeCNAME uint16 = 5
    13		TypePTR   uint16 = 12
    14		TypeMX    uint16 = 15
    15		TypeSRV   uint16 = 33
    16		TypeDNAME uint16 = 39
    17		TypeOPT   uint16 = 41
    18		maxRdata         = 65535
    19	)
    20	
    21	var ErrInvalidData = errors.New("dnsdata: invalid sync data")
    22	
    23	func invalidf(format string, args ...any) error {
    24		return fmt.Errorf("%w: "+format, append([]any{ErrInvalidData}, args...)...)
    25	}
    26	
    27	func canonicalChar(c byte) bool {
    28		return c >= 0x21 && c <= 0x7e && c != '.' && c != '\\' && (c < 'A' || c > 'Z')
    29	}
    30	
    31	func ValidName(name string) bool {
    32		if name == "." {
    33			return true
    34		}
    35		if name == "" || !strings.HasSuffix(name, ".") {
    36			return false
    37		}
    38		wire := 1
    39		start := 0
    40		for i := 0; i < len(name); i++ {
    41			if name[i] == '.' {
    42				n := i - start
    43				if n == 0 || n > maxLabel {
    44					return false
    45				}
    46				wire += n + 1
    47				start = i + 1
    48				continue
    49			}
    50			if !canonicalChar(name[i]) {
    51				return false
    52			}
    53		}
    54		return wire <= maxName
    55	}
    56	
    57	func InZone(owner, apex string) bool {
    58		if apex == "." || owner == apex {
    59			return true
    60		}
    61		return strings.HasSuffix(owner, "."+apex)
    62	}
    63	
    64	func ValidType(t uint32) bool {
    65		return t != 0 && t <= 0xffff && t != uint32(TypeOPT) && (t < 128 || t > 255)
    66	}
    67	
    68	func uncompressedNameLen(b []byte) (int, bool) {
    69		pos := 0
    70		for {
    71			if pos >= len(b) {
    72				return 0, false
    73			}
    74			n := int(b[pos])
    75			if n&0xc0 != 0 {
    76				return 0, false
    77			}
    78			pos++
    79			if n == 0 {
    80				return pos, pos <= maxName
    81			}
    82			pos += n
    83			if pos > maxName {
    84				return 0, false
    85			}
    86		}
    87	}
    88	
    89	func nameOffset(t uint32) (int, bool) {
    90		switch t {
    91		case uint32(TypeNS), uint32(TypeCNAME), uint32(TypeDNAME), uint32(TypePTR):
    92			return 0, true
    93		case uint32(TypeMX):
    94			return 2, true
    95		case uint32(TypeSRV):
    96			return 6, true
    97		}
    98		return 0, false
    99	}
   100	
   101	func validRdata(t uint32, rd []byte) bool {
   102		if t == uint32(TypeSOA) {
   103			a, ok := uncompressedNameLen(rd)
   104			if !ok {
   105				return false
   106			}
   107			b, ok := uncompressedNameLen(rd[a:])
   108			return ok && a+b+20 == len(rd)
   109		}
   110		off, ok := nameOffset(t)
   111		if !ok {
   112			return true
   113		}
   114		if len(rd) < off {
   115			return false
   116		}
   117		n, ok := uncompressedNameLen(rd[off:])
   118		return ok && off+n == len(rd)
   119	}
   120	
   121	func ValidateRRSet(apex string, set *syncv1.RRSet) error {
   122		if set == nil {
   123			return invalidf("missing rrset")
   124		}
   125		if !ValidName(set.GetOwner()) {
   126			return invalidf("owner %q is not a canonical name", set.GetOwner())
   127		}
   128		if !InZone(set.GetOwner(), apex) {
   129			return invalidf("owner %q is outside zone %q", set.GetOwner(), apex)
   130		}
   131		if set.GetRrClass() != uint32(ClassIN) {
   132			return invalidf("%s class %d is not IN", set.GetOwner(), set.GetRrClass())
   133		}
   134		if !ValidType(set.GetType()) {
   135			return invalidf("%s type %d is not allowed", set.GetOwner(), set.GetType())
   136		}
   137		if len(set.GetRdata()) == 0 {
   138			return invalidf("%s type %d has no rdata", set.GetOwner(), set.GetType())
   139		}
   140		distinct := map[string]bool{}
   141		for _, rd := range set.GetRdata() {
   142			if len(rd) > maxRdata {
   143				return invalidf("%s type %d rdata is longer than 65535 octets", set.GetOwner(), set.GetType())
   144			}
   145			if !validRdata(set.GetType(), rd) {
   146				return invalidf("%s type %d rdata is malformed", set.GetOwner(), set.GetType())
   147			}
   148			distinct[string(rd)] = true
   149		}
   150		switch set.GetType() {
   151		case uint32(TypeCNAME), uint32(TypeDNAME), uint32(TypeSOA):
   152			if len(distinct) != 1 {
   153				return invalidf("%s type %d must have exactly one rdata", set.GetOwner(), set.GetType())
   154			}
   155		}
   156		return nil
   157	}
   158	
   159	type setKey struct {
   160		owner string
   161		typ   uint32
   162		class uint32
   163	}
   164	
   165	func ValidateZone(z *syncv1.Zone) error {
   166		if z == nil || !ValidName(z.GetApex()) {
   167			return invalidf("zone apex %q is not a canonical name", z.GetApex())
   168		}
   169		seen := map[setKey]bool{}
   170		for _, set := range z.GetRrsets() {
   171			if err := ValidateRRSet(z.GetApex(), set); err != nil {
   172				return err
   173			}
   174			k := setKey{set.GetOwner(), set.GetType(), set.GetRrClass()}
   175			if seen[k] {
   176				return invalidf("duplicate rrset %s type %d in zone %s", k.owner, k.typ, z.GetApex())
   177			}
   178			seen[k] = true
   179		}
   180		return nil
   181	}
   182	
   183	func SanitizeZone(z *syncv1.Zone) (*syncv1.Zone, []error) {
   184		if z == nil || !ValidName(z.GetApex()) {
   185			return nil, []error{invalidf("zone apex %q is not a canonical name", z.GetApex())}
   186		}
   187		var problems []error
   188		out := &syncv1.Zone{Apex: z.GetApex()}
   189		seen := map[setKey]bool{}
   190		for _, set := range z.GetRrsets() {
   191			if err := ValidateRRSet(z.GetApex(), set); err != nil {
   192				problems = append(problems, fmt.Errorf("zone %s: %w", z.GetApex(), err))
   193				continue
   194			}
   195			k := setKey{set.GetOwner(), set.GetType(), set.GetRrClass()}
   196			if seen[k] {
   197				problems = append(problems, invalidf("duplicate rrset %s type %d in zone %s", k.owner, k.typ, z.GetApex()))
   198				continue
   199			}
   200			seen[k] = true
   201			out.Rrsets = append(out.Rrsets, set)
   202		}
   203		return out, problems
   204	}
   205	
   206	func SanitizeZones(zones []*syncv1.Zone) ([]*syncv1.Zone, []error) {
   207		var problems []error
   208		out := make([]*syncv1.Zone, 0, len(zones))
   209		seen := map[string]bool{}
   210		for _, z := range zones {
   211			clean, errs := SanitizeZone(z)
   212			problems = append(problems, errs...)
   213			if clean == nil {
   214				continue
   215			}
   216			if seen[clean.GetApex()] {
   217				problems = append(problems, invalidf("duplicate zone %s", clean.GetApex()))
   218				continue
   219			}
   220			seen[clean.GetApex()] = true
   221			out = append(out, clean)
   222		}
   223		return out, problems
   224	}
   225	
   226	func SanitizeOps(ops []*syncv1.Op) ([]*syncv1.Op, []error) {
   227		var problems []error
   228		out := make([]*syncv1.Op, 0, len(ops))
   229		for _, op := range ops {
   230			switch v := op.GetOp().(type) {
   231			case *syncv1.Op_PutZone:
   232				clean, errs := SanitizeZone(v.PutZone)
   233				problems = append(problems, errs...)
   234				if clean != nil {
   235					out = append(out, PutZone(clean))
   236				}
   237			case *syncv1.Op_DeleteZone:
   238				if !ValidName(v.DeleteZone) {
   239					problems = append(problems, invalidf("delete_zone apex %q is not a canonical name", v.DeleteZone))
   240					continue
   241				}
   242				out = append(out, op)
   243			case *syncv1.Op_PutRrset:
   244				apex := v.PutRrset.GetApex()
   245				set := v.PutRrset.GetRrset()
   246				if !ValidName(apex) || set == nil || !ValidName(set.GetOwner()) || !InZone(set.GetOwner(), apex) {
   247					problems = append(problems, invalidf("put_rrset with an invalid zone, owner or empty rrset (zone %q)", apex))
   248					continue
   249				}
   250				if err := ValidateRRSet(apex, set); err != nil {
   251					problems = append(problems, fmt.Errorf("put_rrset replaced by delete_rrset: %w", err))
   252					out = append(out, &syncv1.Op{Op: &syncv1.Op_DeleteRrset{DeleteRrset: &syncv1.RRSetKey{Apex: apex, Owner: set.GetOwner(), Type: set.GetType(), RrClass: set.GetRrClass()}}})
   253					continue
   254				}
   255				out = append(out, op)
   256			case *syncv1.Op_DeleteRrset:
   257				k := v.DeleteRrset
   258				if k == nil || !ValidName(k.GetApex()) || !ValidName(k.GetOwner()) {
   259					problems = append(problems, invalidf("delete_rrset with an invalid zone or owner"))
   260					continue
   261				}
   262				out = append(out, op)
   263			default:
   264				problems = append(problems, invalidf("op without a variant"))
   265			}
   266		}
   267		return out, problems
   268	}

