    51	func (rt route) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    52		if h, ok := rt[r.Method]; ok {
    53			h.ServeHTTP(w, r)
    54			return
    55		}
    56		allowed := make([]string, 0, len(rt))
    57		for m := range rt {
