    85	func (a *API) report(w http.ResponseWriter, r *http.Request, err error) {
    86		httpx.ReportError(a.log, w, r, toHTTP(err))
    87	}
    88	
    89	func (a *API) public(h handlerFunc) http.Handler {
    90		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    91			w.Header().Set("Cache-Control", "no-store")
    92			if err := h(w, r); err != nil {
    93				a.report(w, r, err)
    94			}
    95		})
    96	}
    97	
    98	func (a *API) authed(h authedFunc) http.Handler {
    99		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   100			w.Header().Set("Cache-Control", "no-store")
   101			sub, err := assertion.FromRequest(a.verifier, r)
   102			if err != nil {
   103				httpx.WriteError(w, httpx.Unauthenticated("authentication required"))
   104				return
   105			}
   106			c, err := a.caller(r, sub)
   107			if err != nil {
   108				httpx.WriteError(w, httpx.Unauthenticated("authentication required"))
   109				return
   110			}
   111			if err := h(w, r, c); err != nil {
   112				a.report(w, r, err)
   113			}
   114		})
   115	}
