   117	func (a *API) caller(r *http.Request, sub assertion.Subject) (core.Caller, error) {
   118		id, err := uuid.Parse(sub.ID)
   119		if err != nil {
   120			return core.Caller{}, err
   121		}
   122		c := core.Caller{Type: rbac.PrincipalType(sub.Type), ID: id}
   123		if sub.Type == assertion.PrincipalServiceAccount {
   124			if c.OrgID, err = uuid.Parse(sub.OrgID); err != nil {
   125				return core.Caller{}, err
   126			}
   127			return c, nil
   128		}
   129		if r.Header.Get("Authorization") != "" {
   130			return c, nil
   131		}
   132		if cookie, cerr := r.Cookie(CookieName); cerr == nil {
   133			if sid, ok := a.svc.SessionFor(r.Context(), cookie.Value, id); ok {
   134				c.SessionID = &sid
   135			}
   136		}
   137		return c, nil
   138	}
