   140	func toHTTP(err error) error {
   141		var ce *core.Error
   142		if !errors.As(err, &ce) {
   143			var he *httpx.Error
   144			if errors.As(err, &he) {
   145				return err
   146			}
   147			return httpx.Internal().WithCause(err)
   148		}
   149		msg := ce.Message
   150		switch ce.Kind {
   151		case core.KindInvalid:
   152			return httpx.Validation(ce.Field, msg)
   153		case core.KindUnauthenticated:
   154			return httpx.Unauthenticated(msg)
   155		case core.KindInvalidCredentials:
   156			return httpx.NewError(http.StatusUnauthorized, httpx.CodeInvalidCredentials, msg)
   157		case core.KindMFAInvalid:
   158			return httpx.NewError(http.StatusUnauthorized, httpx.CodeMFAInvalid, msg)
   159		case core.KindForbidden:
   160			return httpx.Forbidden(msg)
   161		case core.KindNotFound:
   162			return httpx.NotFound(msg)
   163		case core.KindConflict, core.KindFailedPrecondition:
   164			return httpx.Conflict(msg)
   165		case core.KindRateLimited:
   166			secs := int(ce.RetryAfter / time.Second)
   167			return httpx.RateLimited(secs)
   168		case core.KindUnavailable:
   169			return httpx.Unavailable(msg).WithCause(err)
   170		}
   171		return httpx.Internal().WithCause(err)
   172	}
