   182	func queryValue(r *http.Request, name string) (*string, error) {
   183		vs, ok := r.URL.Query()[name]
   184		if !ok {
   185			return nil, nil
   186		}
   187		if len(vs) != 1 {
   188			return nil, httpx.Validation(name, "must be given at most once")
   189		}
   190		return &vs[0], nil
   191	}
