   193	func queryInt(r *http.Request, name string, def int) (int, error) {
   194		v, err := queryValue(r, name)
   195		if err != nil || v == nil {
   196			return def, err
   197		}
   198		if *v == "" || strings.TrimSpace(*v) != *v || len(*v) > 9 {
   199			return 0, httpx.Validation(name, "must be an integer")
   200		}
   201		n, err := strconv.Atoi(*v)
   202		if err != nil {
   203			return 0, httpx.Validation(name, "must be an integer")
   204		}
   205		return n, nil
   206	}
