    59	func (s *Service) Login(ctx context.Context, username, pw string) (LoginResult, error) {
    60		if err := checkUsername("username", username); err != nil {
    61			return LoginResult{}, err
    62		}
    63		if err := checkPassword("password", pw); err != nil {
    64			return LoginResult{}, err
    65		}
    66		var u store.User
    67		err := s.inTx(ctx, func(tx store.Tx) error {
    68			var err error
    69			u, err = tx.UserByUsername(ctx, username)
    70			return err
    71		})
    72		if KindOf(err) == KindInternal && errors.Is(err, store.ErrNotFound) {
    73			if derr := s.hasher.VerifyDummy(ctx, pw); derr != nil {
    74				return LoginResult{}, s.hashErr(derr)
    75			}
    76			return LoginResult{}, invalidCredentials()
    77		}
    78		if err != nil {
    79			return LoginResult{}, err
    80		}
    81		ok, err := s.hasher.Verify(ctx, pw, u.PasswordHash)
    82		if err != nil {
    83			return LoginResult{}, s.hashErr(err)
    84		}
    85		if !ok {
    86			return LoginResult{}, invalidCredentials()
    87		}
    88		if u.TOTPEnabled {
    89			return s.startMFA(ctx, u)
    90		}
    91		return s.finishLogin(ctx, u, func(store.Tx) error { return nil })
    92	}
