    94	func (s *Service) startMFA(ctx context.Context, u store.User) (LoginResult, error) {
    95		tok, err := token.New(token.KindMFA)
    96		if err != nil {
    97			return LoginResult{}, internal(err)
    98		}
    99		now := s.clock()
   100		c := store.MFAChallenge{ID: tok.ID, UserID: u.ID, SecretHash: tok.Hash(), CreatedAt: now, ExpiresAt: now.Add(s.cfg.MFATTL)}
   101		if err := s.inTx(ctx, func(tx store.Tx) error { return tx.CreateMFAChallenge(ctx, c) }); err != nil {
   102			return LoginResult{}, err
   103		}
   104		return LoginResult{User: u, MFARequired: true, MFAToken: tok.String(), MFAExpiresAt: c.ExpiresAt}, nil
   105	}
   106	
   107	func (s *Service) finishLogin(ctx context.Context, u store.User, inTx func(store.Tx) error) (LoginResult, error) {
   108		tok, err := token.New(token.KindSession)
   109		if err != nil {
   110			return LoginResult{}, internal(err)
   111		}
   112		now := s.clock()
   113		sess := store.Session{ID: tok.ID, UserID: u.ID, SecretHash: tok.Hash(), CreatedAt: now, LastSeenAt: now, ExpiresAt: now.Add(s.cfg.SessionTTL), AbsoluteExpiresAt: now.Add(s.cfg.SessionAbsolute)}
   114		if sess.ExpiresAt.After(sess.AbsoluteExpiresAt) {
   115			sess.ExpiresAt = sess.AbsoluteExpiresAt
   116		}
   117		err = s.inTx(ctx, func(tx store.Tx) error {
   118			if err := inTx(tx); err != nil {
   119				return err
   120			}
   121			return tx.CreateSession(ctx, sess)
   122		})
   123		if err != nil {
   124			return LoginResult{}, err
   125		}
   126		s.ensureDefaultOrg(ctx, u)
   127		return LoginResult{User: u, SessionToken: tok.String(), SessionExpires: sess.AbsoluteExpiresAt, SessionMaxAge: sess.AbsoluteExpiresAt.Sub(now)}, nil
   128	}
