    26	func (s *Service) Register(ctx context.Context, username, pw string) (store.User, error) {
    27		if err := checkUsername("username", username); err != nil {
    28			return store.User{}, err
    29		}
    30		if err := checkPassword("password", pw); err != nil {
    31			return store.User{}, err
    32		}
    33		hash, err := s.hasher.Hash(ctx, pw)
    34		if err != nil {
    35			return store.User{}, s.hashErr(err)
    36		}
    37		id, err := newID()
    38		if err != nil {
    39			return store.User{}, internal(err)
    40		}
    41		now := s.clock()
    42		u := store.User{ID: id, Username: username, PasswordHash: hash, CreatedAt: now, UpdatedAt: now}
    43		err = s.inTx(ctx, func(tx store.Tx) error {
    44			if err := tx.CreateUser(ctx, u); err != nil {
    45				if errors.Is(err, store.ErrConflict) {
    46					return conflict("username is already taken")
    47				}
    48				return err
    49			}
    50			return nil
    51		})
    52		if err != nil {
    53			return store.User{}, err
    54		}
    55		s.ensureDefaultOrg(ctx, u)
    56		return u, nil
    57	}
