   131	
   132	func (s *Service) LoginTOTP(ctx context.Context, mfaToken string, code, recovery *string) (LoginResult, error) {
   133		tok, err := token.ParseKind(mfaToken, token.KindMFA)
   134		if err != nil {
   135			return LoginResult{}, invalid("mfa_token", "must be an sdmfa token")
   136		}
   137		normalized, err := secondFactorInput(code, recovery, "code", "recovery_code")
   138		if err != nil {
   139			return LoginResult{}, err
   140		}
   141		now := s.clock()
   142		var c store.MFAChallenge
   143		var u store.User
   144		attempt := 0
   145		err = s.inTx(ctx, func(tx store.Tx) error {
   146			var err error
   147			c, err = tx.MFAChallengeByID(ctx, tok.ID)
   148			if errors.Is(err, store.ErrNotFound) {
   149				return mfaInvalid()
   150			}
   151			if err != nil {
   152				return err
   153			}
   154			if !token.Equal(c.SecretHash, tok.Secret) || c.UsedAt != nil || !now.Before(c.ExpiresAt) || c.FailedAttempts >= store.MaxMFAFailures {
   155				return mfaInvalid()
   156			}
   157			attempt, err = tx.ReserveMFAAttempt(ctx, c.ID, now)
   158			if err != nil {
   159				return err
   160			}
   161			if attempt == 0 {
   162				return mfaInvalid()
   163			}
   164			u, err = tx.UserByID(ctx, c.UserID)
   165			return err
   166		})
   167		if err != nil {
   168			return LoginResult{}, err
   169		}
   170		if attempt > store.MaxMFAAttempts {
   171			if ferr := s.failMFA(ctx, c.ID); ferr != nil {
   172				return LoginResult{}, ferr
   173			}
   174			return LoginResult{}, mfaInvalid()
   175		}
   176		res, err := s.finishLogin(ctx, u, func(tx store.Tx) error {
   177			if err := s.verifySecondFactor(ctx, tx, u.ID, code != nil, normalized, now); err != nil {
   178				return err
   179			}
   180			ok, err := tx.ConsumeMFAChallenge(ctx, c.ID, now)
   181			if err != nil {
   182				return err
   183			}
   184			if !ok {
   185				return mfaInvalid()
   186			}
   187			return nil
   188		})
   189		if errors.Is(err, errVerification) {
   190			if ferr := s.failMFA(ctx, c.ID); ferr != nil {
   191				return LoginResult{}, ferr
   192			}
   193			return LoginResult{}, mfaInvalid()
   194		}
   195		return res, err
   196	}
