   205	func secondFactorInput(code, recovery *string, codeField, recoveryField string) (string, error) {
   206		switch {
   207		case code != nil && recovery != nil:
   208			return "", invalid(recoveryField, "send either "+codeField+" or "+recoveryField+", not both")
   209		case code == nil && recovery == nil:
   210			return "", invalid(codeField, "is required")
   211		case code != nil:
   212			return *code, checkTOTPCode(codeField, *code)
   213		default:
   214			return checkRecoveryCode(recoveryField, *recovery)
   215		}
   216	}
