    14	const TrustDomain = "spiffe://slopdns/"
    15	
    16	const DNSServerURIPrefix = TrustDomain + "dns-server/"
    17	
    18	var ErrPeerIdentity = errors.New("peer certificate identity not allowed")
    19	
    20	type Files struct {
    21		CA   string
    22		Cert string
    23		Key  string
    24	}
    25	
    26	type Material struct {
    27		CAs  *x509.CertPool
    28		Cert tls.Certificate
    29	}
    30	
    31	func FilesIn(dir, name string) Files {
    32		return Files{
    33			CA:   filepath.Join(dir, "ca.crt"),
    34			Cert: filepath.Join(dir, name+".crt"),
    35			Key:  filepath.Join(dir, name+".key"),
    36		}
    37	}
    38	
    39	func ServiceURI(service string) string {
    40		return TrustDomain + service
    41	}
