    43	func DNSNodeURI(nodeID string) string {
    44		return DNSServerURIPrefix + nodeID
    45	}
    46	
    47	func Load(f Files) (*Material, error) {
    48		caPEM, err := os.ReadFile(f.CA)
    49		if err != nil {
    50			return nil, fmt.Errorf("read CA: %w", err)
    51		}
    52		certPEM, err := os.ReadFile(f.Cert)
    53		if err != nil {
    54			return nil, fmt.Errorf("read certificate: %w", err)
    55		}
    56		keyPEM, err := os.ReadFile(f.Key)
    57		if err != nil {
    58			return nil, fmt.Errorf("read key: %w", err)
    59		}
    60		return Parse(caPEM, certPEM, keyPEM)
    61	}
    62	
    63	func Parse(caPEM, certPEM, keyPEM []byte) (*Material, error) {
    64		pool := x509.NewCertPool()
    65		if !pool.AppendCertsFromPEM(caPEM) {
    66			return nil, errors.New("CA bundle contains no certificates")
    67		}
    68		cert, err := tls.X509KeyPair(certPEM, keyPEM)
    69		if err != nil {
    70			return nil, fmt.Errorf("load key pair: %w", err)
    71		}
    72		if cert.Leaf == nil {
    73			leaf, err := x509.ParseCertificate(cert.Certificate[0])
    74			if err != nil {
    75				return nil, fmt.Errorf("parse leaf: %w", err)
    76			}
    77			cert.Leaf = leaf
    78		}
    79		if _, err := cert.Leaf.Verify(x509.VerifyOptions{Roots: pool, KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageAny}}); err != nil {
    80			return nil, fmt.Errorf("certificate is not signed by the configured CA: %w", err)
    81		}
    82		return &Material{CAs: pool, Cert: cert}, nil
    83	}
    84	
    85	type PeerVerifier func(leaf *x509.Certificate) error
    86	
    87	func URIs(cert *x509.Certificate) []string {
    88		out := make([]string, 0, len(cert.URIs))
    89		for _, u := range cert.URIs {
    90			out = append(out, u.String())
    91		}
    92		return out
    93	}
    94	
    95	func AllowURIs(allowed ...string) PeerVerifier {
    96		return func(leaf *x509.Certificate) error {
    97			for _, u := range URIs(leaf) {
    98				if slices.Contains(allowed, u) {
    99					return nil
   100				}
   101			}
   102			return fmt.Errorf("%w: URI SANs %v, allowed %v", ErrPeerIdentity, URIs(leaf), allowed)
   103		}
   104	}
   105	
   106	func AllowURIPrefix(prefix string) PeerVerifier {
   107		return func(leaf *x509.Certificate) error {
   108			for _, u := range URIs(leaf) {
   109				if rest, ok := strings.CutPrefix(u, prefix); ok && ValidNodeID(rest) {
   110					return nil
   111				}
   112			}
   113			return fmt.Errorf("%w: URI SANs %v, want prefix %s", ErrPeerIdentity, URIs(leaf), prefix)
   114		}
   115	}
   116	
   117	func DNSNodeID(leaf *x509.Certificate) (string, error) {
   118		var found []string
   119		for _, u := range URIs(leaf) {
   120			if rest, ok := strings.CutPrefix(u, DNSServerURIPrefix); ok && ValidNodeID(rest) {
   121				found = append(found, rest)
   122			}
   123		}
   124		if len(found) != 1 {
   125			return "", fmt.Errorf("%w: expected exactly one %s<node-id> URI SAN", ErrPeerIdentity, DNSServerURIPrefix)
   126		}
   127		return found[0], nil
   128	}
   129	
   130	func ValidNodeID(s string) bool {
   131		if s == "" || len(s) > 63 {
   132			return false
   133		}
   134		for i := 0; i < len(s); i++ {
   135			c := s[i]
   136			if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '-' {
   137				return false
   138			}
   139		}
   140		return s[0] != '-' && s[len(s)-1] != '-'
   141	}
