   143	func ServerConfig(m *Material, verify PeerVerifier) (*tls.Config, error) {
   144		if verify == nil {
   145			return nil, errors.New("mtls: server requires a peer verifier")
   146		}
   147		return &tls.Config{
   148			MinVersion:   tls.VersionTLS13,
   149			Certificates: []tls.Certificate{m.Cert},
   150			ClientCAs:    m.CAs,
   151			ClientAuth:   tls.RequireAndVerifyClientCert,
   152			NextProtos:   []string{"h2"},
   153			VerifyConnection: func(cs tls.ConnectionState) error {
   154				if len(cs.PeerCertificates) == 0 {
   155					return fmt.Errorf("%w: no client certificate", ErrPeerIdentity)
   156				}
   157				return verify(cs.PeerCertificates[0])
   158			},
   159		}, nil
   160	}
   161	
   162	func ClientConfig(m *Material, serverName string, verify PeerVerifier) (*tls.Config, error) {
   163		if serverName == "" {
   164			return nil, errors.New("mtls: client requires a server name")
   165		}
   166		cfg := &tls.Config{
   167			MinVersion:   tls.VersionTLS13,
   168			Certificates: []tls.Certificate{m.Cert},
   169			RootCAs:      m.CAs,
   170			ServerName:   serverName,
   171			NextProtos:   []string{"h2"},
   172		}
   173		if verify != nil {
   174			cfg.VerifyConnection = func(cs tls.ConnectionState) error {
   175				if len(cs.PeerCertificates) == 0 {
   176					return fmt.Errorf("%w: no server certificate", ErrPeerIdentity)
   177				}
   178				return verify(cs.PeerCertificates[0])
   179			}
   180		}
   181		return cfg, nil
   182	}
   183	
   184	func PeerLeaf(cs *tls.ConnectionState) (*x509.Certificate, error) {
   185		if cs == nil || len(cs.VerifiedChains) == 0 || len(cs.VerifiedChains[0]) == 0 {
   186			return nil, fmt.Errorf("%w: no verified peer certificate", ErrPeerIdentity)
   187		}
   188		return cs.VerifiedChains[0][0], nil
   189	}
