   152	func parseTypeNumber(s string) (uint32, bool) {
   153		if !strings.HasPrefix(s, "TYPE") {
   154			return 0, false
   155		}
   156		digits := s[4:]
   157		if digits == "" || len(digits) > 5 || digits[0] == '0' {
   158			return 0, false
   159		}
   160		for i := 0; i < len(digits); i++ {
   161			if !isDigit(digits[i]) {
   162				return 0, false
   163			}
   164		}
   165		n, err := strconv.ParseUint(digits, 10, 32)
   166		if err != nil {
   167			return 0, false
   168		}
   169		return uint32(n), true
   170	}
