   198	func jsonFields(dst any) map[string]bool {
   199		t := reflect.TypeOf(dst)
   200		for t.Kind() == reflect.Pointer {
   201			t = t.Elem()
   202		}
   203		out := map[string]bool{}
   204		for i := 0; i < t.NumField(); i++ {
