   218		}
   219		seen := map[string]bool{}
   220		for dec.More() {
   221			tok, err := dec.Token()
   222			if err != nil {
   223				return &SyntaxError{Message: "field data is malformed"}
   224			}
   225			key, ok := tok.(string)
   226			if !ok {
   227				return &SyntaxError{Message: "field data is malformed"}
   228			}
   229			if !allowed[key] {
   230				return &SyntaxError{Message: "unknown field data." + key}
   231			}
   232			if seen[key] {
   233				return &SyntaxError{Message: "duplicate field data." + key}
   234			}
   235			seen[key] = true
   236			var skip json.RawMessage
   237			if err := dec.Decode(&skip); err != nil {
   238				return &SyntaxError{Message: "field data is malformed"}
   239			}
   240		}
   241		return nil
   242	}
