   254				return &SyntaxError{Message: "field data." + typeErr.Field + " has wrong type"}
   255			case strings.HasPrefix(err.Error(), "json: unknown field "):
   256				name := strings.Trim(strings.TrimPrefix(err.Error(), "json: unknown field "), "\"")
