   258			}
   259			return &SyntaxError{Message: "field data is malformed"}
   260		}
   261		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
   262			return &SyntaxError{Message: "field data is malformed"}
   263		}
   264		return nil
   265	}
