    73	func (p Params) validate() error {
    74		switch {
    75		case p.Memory < 8 || p.Memory > maxMemory:
    76			return errors.New("password: memory out of range")
    77		case p.Time < 1 || p.Time > maxTime:
    78			return errors.New("password: time out of range")
    79		case p.Threads < 1:
    80			return errors.New("password: threads out of range")
    81		case p.SaltLen < 8 || p.SaltLen > maxSaltLen:
    82			return errors.New("password: salt length out of range")
    83		case p.KeyLen < 16 || p.KeyLen > maxKeyLen:
    84			return errors.New("password: key length out of range")
    85		}
    86		return nil
    87	}
