   105	func (h *Hasher) acquire(ctx context.Context) error {
   106		select {
   107		case h.sem <- struct{}{}:
   108			return nil
   109		default:
   110		}
   111		timer := time.NewTimer(h.queueTimeout)
   112		defer timer.Stop()
   113		select {
   114		case h.sem <- struct{}{}:
   115			return nil
   116		case <-timer.C:
   117			return ErrBusy
   118		case <-ctx.Done():
   119			return ctx.Err()
   120		}
   121	}
