   123	func (h *Hasher) release() {
   124		<-h.sem
   125	}
   126	
   127	func (h *Hasher) Hold(ctx context.Context) (func(), error) {
   128		if err := h.acquire(ctx); err != nil {
   129			return nil, err
   130		}
   131		return h.release, nil
   132	}
