   134	func (h *Hasher) Hash(ctx context.Context, pw string) (string, error) {
   135		if len(pw) > MaxLength*utf8.UTFMax {
   136			return "", ErrTooLong
   137		}
   138		salt := make([]byte, h.params.SaltLen)
   139		if _, err := rand.Read(salt); err != nil {
   140			return "", err
   141		}
   142		if err := h.acquire(ctx); err != nil {
   143			return "", err
   144		}
   145		key := argon2.IDKey([]byte(pw), salt, h.params.Time, h.params.Memory, h.params.Threads, h.params.KeyLen)
   146		h.release()
   147		enc := base64.RawStdEncoding
   148		return fmt.Sprintf("$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s", argon2.Version, h.params.Memory, h.params.Time, h.params.Threads, enc.EncodeToString(salt), enc.EncodeToString(key)), nil
   149	}
