   151	func (h *Hasher) Verify(ctx context.Context, pw, encoded string) (bool, error) {
   152		p, salt, key, err := Decode(encoded)
   153		if err != nil {
   154			return false, err
   155		}
   156		if len(pw) > MaxLength*utf8.UTFMax {
   157			return false, nil
   158		}
   159		if err := h.acquire(ctx); err != nil {
   160			return false, err
   161		}
   162		got := argon2.IDKey([]byte(pw), salt, p.Time, p.Memory, p.Threads, byteLen(key))
   163		h.release()
   164		return subtle.ConstantTimeCompare(got, key) == 1, nil
   165	}
