   172	func (h *Hasher) NeedsRehash(encoded string) bool {
   173		p, salt, key, err := Decode(encoded)
   174		if err != nil {
   175			return true
   176		}
   177		return p.Memory != h.params.Memory || p.Time != h.params.Time || p.Threads != h.params.Threads || byteLen(salt) != h.params.SaltLen || byteLen(key) != h.params.KeyLen
   178	}
   179	
   180	func Decode(encoded string) (Params, []byte, []byte, error) {
   181		parts := strings.Split(encoded, "$")
   182		if len(parts) != 6 || parts[0] != "" || parts[1] != "argon2id" {
   183			return Params{}, nil, nil, ErrInvalidHash
   184		}
   185		var version int
   186		if _, err := fmt.Sscanf(parts[2], "v=%d", &version); err != nil || version != argon2.Version || parts[2] != fmt.Sprintf("v=%d", version) {
   187			return Params{}, nil, nil, ErrInvalidHash
   188		}
   189		var p Params
   190		var threads uint32
   191		if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &p.Memory, &p.Time, &threads); err != nil {
   192			return Params{}, nil, nil, ErrInvalidHash
   193		}
   194		if parts[3] != fmt.Sprintf("m=%d,t=%d,p=%d", p.Memory, p.Time, threads) || threads < 1 || threads > 255 {
   195			return Params{}, nil, nil, ErrInvalidHash
   196		}
   197		p.Threads = uint8(threads)
   198		enc := base64.RawStdEncoding.Strict()
   199		salt, err := enc.DecodeString(parts[4])
   200		if err != nil {
   201			return Params{}, nil, nil, ErrInvalidHash
   202		}
   203		key, err := enc.DecodeString(parts[5])
   204		if err != nil {
   205			return Params{}, nil, nil, ErrInvalidHash
   206		}
   207		p.SaltLen = byteLen(salt)
   208		p.KeyLen = byteLen(key)
   209		if err := p.validate(); err != nil {
   210			return Params{}, nil, nil, ErrInvalidHash
   211		}
   212		return p, salt, key, nil
   213	}
