    99	func writeNew(path string, data []byte, mode os.FileMode) error {
   100		tmp, err := os.CreateTemp(filepath.Dir(path), ".pkigen-*")
   101		if err != nil {
   102			return err
   103		}
   104		tmpName := tmp.Name()
   105		defer func() { _ = os.Remove(tmpName) }()
   106		if _, err := tmp.Write(data); err != nil {
   107			_ = tmp.Close()
   108			return err
   109		}
   110		if err := tmp.Chmod(mode); err != nil {
   111			_ = tmp.Close()
   112			return err
   113		}
   114		if err := tmp.Sync(); err != nil {
   115			_ = tmp.Close()
   116			return err
   117		}
   118		if err := tmp.Close(); err != nil {
   119			return err
   120		}
   121		return os.Link(tmpName, path)
   122	}
