    51	func (s *Service) BootstrapInfra(ctx context.Context, zoneName, address string) (BootstrapResult, error) {
    52		var res BootstrapResult
    53		if !ValidIPv4(address) {
    54			return res, fmt.Errorf("infra NS address %q is not a dotted-quad IPv4 address", address)
    55		}
    56		a, err := rrdata.Parse("A", []byte(`{"address":"`+address+`"}`))
    57		if err != nil {
    58			return res, err
    59		}
    60		var hosts []string
    61		for _, ns := range s.defaults.NameServers {
    62			if dnsname.IsStrictSubdomain(ns, zoneName) {
    63				hosts = append(hosts, ns)
    64			}
    65		}
    66		err = s.store.InTx(ctx, func(q *store.Q) error {
    67			if err := q.LockZoneTree(ctx); err != nil {
    68				return err
    69			}
    70			org, err := q.GetDefaultOrg(ctx, SystemPrincipal)
    71			if errors.Is(err, store.ErrNotFound) {
    72				sys := SystemPrincipal
    73				org, err = q.InsertOrg(ctx, store.Org{ID: newID(), Name: SystemOrgName, DefaultForUserID: &sys, CreatedBy: SystemPrincipal})
    74				res.OrgCreated = true
    75			}
    76			if err != nil {
    77				return err
    78			}
    79			res.OrgID = org.ID
    80			zone, err := q.LockZoneByName(ctx, zoneName)
    81			if errors.Is(err, store.ErrNotFound) {
    82				extra := make([]extraRecord, 0, len(hosts))
    83				for _, h := range hosts {
    84					extra = append(extra, extraRecord{owner: h, rec: a})
    85				}
    86				zone, err = s.insertZone(ctx, q, store.Zone{
    87					ID: newID(), OrgID: org.ID, Name: zoneName, SOAMName: s.defaults.MName, SOARName: s.defaults.RName, SOASerial: 1,
    88					SOARefresh: s.defaults.Refresh, SOARetry: s.defaults.Retry, SOAExpire: s.defaults.Expire, SOAMinimum: s.defaults.Minimum, DefaultTTL: s.defaults.DefaultTTL,
    89				}, extra)
    90				if err != nil {
    91					return err
    92				}
    93				res.ZoneID, res.Zone, res.ZoneCreated = zone.ID, zone.Name, true
    94				return nil
    95			}
    96			if err != nil {
    97				return err
    98			}
    99			if zone.OrgID != org.ID {
   100				return fmt.Errorf("zone %s exists but belongs to organization %s, not to %s", zoneName, zone.OrgID, SystemOrgName)
   101			}
   102			res.ZoneID, res.Zone = zone.ID, zone.Name
   103			var keys [][2]any
   104			for _, h := range hosts {
   105				members, err := q.RRSet(ctx, zone.ID, h, int32(rrdata.TypeA))
   106				if err != nil {
   107					return err
   108				}
   109				if len(members) == 1 && string(members[0].Wire) == string(a.Wire) {
   110					continue
   111				}
   112				for _, m := range members {
   113					if err := q.DeleteRecord(ctx, m.ID); err != nil {
   114						return err
   115					}
   116				}
   117				data, err := a.DataJSON()
   118				if err != nil {
   119					return err
   120				}
   121				if _, err := q.InsertRecord(ctx, store.Record{ID: newID(), ZoneID: zone.ID, Owner: h, Type: int32(rrdata.TypeA), TTL: zone.DefaultTTL, Data: data, Wire: a.Wire}); err != nil {
   122					return err
   123				}
   124				keys = append(keys, [2]any{h, int32(rrdata.TypeA)})
   125				res.Updated = append(res.Updated, h)
   126			}
   127			if len(keys) == 0 {
   128				return nil
   129			}
   130			return s.finishChange(ctx, q, zone, keys)
   131		})
   132		return res, err
   133	}
