   137	func Serve(ctx context.Context, logger *slog.Logger, srv *http.Server, ln net.Listener, shutdownTimeout time.Duration) error {
   138		if shutdownTimeout <= 0 {
   139			shutdownTimeout = DefaultShutdownTimeout
   140		}
   141		errCh := make(chan error, 1)
   142		go func() {
   143			errCh <- srv.Serve(ln)
   144		}()
   145		logger.InfoContext(ctx, "http server listening", slog.String("addr", ln.Addr().String()))
   146		select {
   147		case err := <-errCh:
   148			if errors.Is(err, http.ErrServerClosed) {
   149				return nil
   150			}
   151			return err
   152		case <-ctx.Done():
   153		}
   154		logger.Info("shutting down http server")
   155		shutdownCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), shutdownTimeout)
   156		defer cancel()
   157		if err := srv.Shutdown(shutdownCtx); err != nil {
   158			return fmt.Errorf("shutdown: %w", err)
   159		}
   160		if err := <-errCh; err != nil && !errors.Is(err, http.ErrServerClosed) {
   161			return err
   162		}
   163		return nil
   164	}
