   166	func ListenAndServe(ctx context.Context, logger *slog.Logger, addr string, handler http.Handler) error {
   167		ln, err := net.Listen("tcp", addr)
   168		if err != nil {
   169			return err
   170		}
   171		return Serve(ctx, logger, NewServer(handler, logger), ln, DefaultShutdownTimeout)
   172	}
