    39	func ReservedNames(d ZoneDefaults) []string {
    40		hosts := append([]string{d.MName, d.RName}, d.NameServers...)
    41		hosts = append(hosts, d.Reserved...)
    42		seen := map[string]bool{}
    43		var out []string
    44		for _, h := range hosts {
    45			name, err := dnsname.Parse(h, dnsname.HostPolicy)
    46			if err != nil {
    47				continue
    48			}
    49			for _, n := range append([]string{name}, dnsname.Ancestors(name, d.Suffix)...) {
    50				if dnsname.IsStrictSubdomain(n, d.Suffix) && !seen[n] {
    51					seen[n] = true
    52					out = append(out, n)
    53				}
    54			}
    55		}
    56		return out
    57	}
