    23	func (s *Service) EnsureDefaultOrg(ctx context.Context, userID, username string) (store.Org, bool, error) {
    24		if !ValidUUID(userID) || !ValidUsername(username) {
    25			return store.Org{}, false, ErrInvalidArgument
    26		}
    27		q := s.store.Q()
    28		if org, err := q.GetDefaultOrg(ctx, userID); err == nil {
    29			return org, false, nil
    30		} else if !errors.Is(err, store.ErrNotFound) {
    31			return store.Org{}, false, err
    32		}
    33		var org store.Org
    34		var ids []string
    35		uid := userID
    36		err := s.store.InTx(ctx, func(tq *store.Q) error {
    37			if err := tq.LockUserOrgQuota(ctx, userID); err != nil {
    38				return err
    39			}
    40			var err error
    41			org, err = tq.InsertOrg(ctx, store.Org{ID: newID(), Name: DefaultOrgName(username), DefaultForUserID: &uid, CreatedBy: userID})
    42			if err != nil {
    43				return err
    44			}
    45			kind, p := outbox.CreateOrgOwner(org.ID, userID)
    46			id, err := outbox.Enqueue(ctx, tq, kind, p)
    47			ids = append(ids, id)
    48			return err
    49		})
    50		if store.IsUnique(err, store.OrgsDefaultUserKey) {
    51			org, err := q.GetDefaultOrg(ctx, userID)
    52			return org, false, err
    53		}
    54		if err != nil {
    55			return store.Org{}, false, err
    56		}
    57		s.afterCommit(ctx, ids)
