    37	func InfraZoneName(d ZoneDefaults, explicit string) (string, error) {
    38		if explicit != "" {
    39			return dnsname.Parse(explicit, dnsname.ZonePolicy)
    40		}
    41		if len(d.NameServers) == 0 {
    42			return "", errors.New("no nameservers configured")
    43		}
    44		parents := dnsname.Ancestors(d.NameServers[0], dnsname.Root)
    45		if len(parents) == 0 || parents[0] == dnsname.Root {
    46			return "", fmt.Errorf("nameserver %s has no parent zone", d.NameServers[0])
    47		}
    48		return parents[0], nil
    49	}
